CREATE VIEW "public"."cost_by_area" AS (select "project_id", "location_id", coalesce("area", '(Tanpa Area)') as "area", coalesce(sum("total"), 0) as "cost", count(*) as "transactions" from "daily_transactions" where "daily_transactions"."kind" = 'cost' group by "daily_transactions"."project_id", "daily_transactions"."location_id", coalesce("daily_transactions"."area", '(Tanpa Area)'));